import json

def deep_merge(a, b):
    if isinstance(a, dict) and isinstance(b, dict):
        res = a.copy()
        for key, value in b.items():
            if key in res:
                res[key] = deep_merge(res[key], value)
            else:
                res[key] = value
        return res
    elif isinstance(a, list) and isinstance(b, list):
        combined = a + b
        result = []
        for item in combined:
            if item not in result:
                result.append(item)
        return result
    else:
        return b

