import re
import sys

def solve():
    log_path = '/tmp/…/app.log'

    level_counts = {}
    component_error_counts = {}
    unique_error_messages = set()
    hour_counts = {}

    try:
        with open(log_path, 'r') as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue

                # Format: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
                # Regex captures: (timestamp, hour, level, component, message)
                match = re.match(r'^\[\d{4}-\d{2}-\d{2} (\d{2}):\d{2}:\d{2}\] (\w+) \(([^)]+)\) - (.*)$', line)
                if match:
                    hour, level, component, message = match.groups()

                    level_counts[level] = level_counts.get(level, 0) + 1

                    if level == 'ERROR':
                        component_error_counts[component] = component_error_counts.get(component, 0) + 1
                        unique_error_messages.add(message)

                    hour_counts[hour] = hour_counts.get(hour, 0) + 1
    except FileNotFoundError:
        return

    print("=== Log Analysis ===")
    print("")
    print("Entries by Level:")
    for level in sorted(level_counts.keys()):
        print(f"  {level}: {level_counts[level]}")
    print("")

    if component_error_counts:
        # Sort by count descending, then by component name ascending for deterministic output
        comp_name, comp_count = sorted(component_error_counts.items(), key=lambda x: (-x[1], x[0]))[0]
        print(f"Component with Most Errors: {comp_name} ({comp_count} errors)")
    else:
        print("Component with Most Errors: None (0 errors)")
    print("")

    print("Unique Error Messages:")
    for msg in sorted(list(unique_error_messages)):
        print(f"  - {msg}")
    print("")

    if hour_counts:
        # Sort by count descending, then by hour ascending for deterministic output
        hour_val, hour_count = sorted(hour_counts.items(), key=lambda x: (-x[1], x[0]))[0]
        print(f"Busiest Hour: {hour_val}:00 ({hour_count} entries)")
    else:
        print("Busiest Hour: 00:00 (0 entries)")

