import * as fs from 'node:fs';

const filePath = '/tmp/…/employees.csv';

function run() {
  const content = fs.readFileSync(filePath, 'utf8');
  const lines = content.split(/\r?\n/).filter(line => line.trim() !== '');

  if (lines.length <= 1) return;

  const employees: { name: string, dept: string, salary: number }[] = [];

  for (let i = 1; i < lines.length; i++) {
    const parts = lines[i].split(',');
    if (parts.length < 4) continue;

    const name = parts[1].trim();
    const dept = parts[2].trim();
    const salary = parseFloat(parts[3].trim());

    if (!isNaN(salary)) {
      employees.push({ name, dept, salary });
    }
  }

  const deptStats = new Map<string, { total: number; count: number }>();
  let highestPaidName = '';
  let highestPaidSalary = -1;
  let totalBudget = 0;

  for (const emp of employees) {
    totalBudget += emp.salary;
    if (emp.salary > highestPaidSalary) {
      highestPaidSalary = emp.salary;
      highestPaidName = emp.name;
    }

    const stats = deptStats.get(emp.dept) || { total: 0, count: 0 };
    stats.total += emp.salary;
    stats.count += 1;
    deptStats.set(emp.dept, stats);
  }

  const avgFormatter = new Intl.NumberFormat('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const intFormatter = new Intl.NumberFormat('en-US');

  console.log('=== Salary Report ===');
  console.log('');
  console.log('Average Salary by Department:');
  const sortedDepts = Array.from(deptStats.keys()).sort();
  for (const dept of sortedDepts) {
    const stats = deptStats.get(dept)!;
    const avg = stats.total / stats.count;
    console.log(`  ${dept}: $${avgFormatter.format(avg)}`);
  }
  console.log('');
  console.log(`Highest Paid: ${highestPaidName} ($${intFormatter.format(highestPaidSalary)})`);
  console.log('');
  console.log('Departments with >2 employees:');
  const filteredDepts = Array.from(deptStats.entries())
    .filter(([_, stats]) => stats.count > 2)
    .sort((a, b) => a[0].localeCompare(b[0]));

  for (const [dept, stats] of filteredDepts) {
    console.log(`  ${dept} (${stats.count} employees)`);
  }
  console.log('');
  console.log(`Total Budget: $${intFormatter.format(totalBudget)}`);
}

