public class Main {
    public static void main(String[] args) {
        String filePath = "/tmp/…/employees.csv";

        TreeMap<String, Double> deptSum = new TreeMap<>();
        TreeMap<String, Integer> deptCount = new TreeMap<>();
        String highestPaidName = "";
        double highestPaidSalary = -1.0;
        double totalBudget = 0;

        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line = br.readLine(); // Skip header
            while ((line = br.readLine()) != null) {
                if (line.trim().isEmpty()) continue;
                String[] parts = line.split(",");
                if (parts.length < 4) continue;

                String name = parts[1].trim();
                String dept = parts[2].trim();
                double salary = Double.parseDouble(parts[3].trim());

                deptSum.put(dept, deptSum.getOrDefault(dept, 0.0) + salary);
                deptCount.put(dept, deptCount.getOrDefault(dept, 0) + 1);
                totalBudget += salary;

                if (salary > highestPaidSalary) {
                    highestPaidSalary = salary;
                    highestPaidName = name;
                }
            }
        } catch (IOException e) {
            return;
        }

        System.out.println("=== Salary Report ===");
        System.out.println();
        System.out.println("Average Salary by Department:");
        for (Map.Entry<String, Double> entry : deptSum.entrySet()) {
            String dept = entry.getKey();
            double avg = entry.getValue() / deptCount.get(dept);
            System.out.printf("  %s: $%,.2f%n", dept, avg);
        }
        System.out.println();
        System.out.printf("Highest Paid: %s ($%,d)%n", highestPaidName, Math.round(highestPaidSalary));
        System.out.println();
        System.out.println("Departments with >2 employees:");
        for (Map.Entry<String, Integer> entry : deptCount.entrySet()) {
            if (entry.getValue() > 2) {
                System.out.printf("  %s (%d employees)%n", entry.getKey(), entry.getValue());
            }
        }
        System.out.println();
        System.out.printf("Total Budget: $%,d%n", Math.round(totalBudget));
    }
}

import Foundation

let filePath = "/tmp/…/employees.csv"

func formatCurrency(value: Double, decimals: Int) -> String {
    let formatter = NumberFormatter()
    formatter.numberStyle = .currency
    formatter.currencySymbol = "$"
    formatter.minimumFractionDigits = decimals
    formatter.maximumFractionDigits = decimals
    formatter.locale = Locale(identifier: "en_US")
    let formatted = formatter.string(from: NSNumber(value: value)) ?? ""
    return formatted.replacingOccurrences(of: "\u{00A0}", with: "").replacingOccurrences(of: " ", with: "")
}

func run() {
    let content: String
    do {
        content = try String(contentsOfFile: filePath, encoding: .utf8)
    } catch {
        return
    }

    let lines = content.components(separatedBy: .newlines).filter { !$0.isEmpty }
    if lines.isEmpty { return }

    var names: [String] = []
    var departments: [String] = []
    var salaries: [Double] = []

    // Skip header row
    for i in 1..<lines.count {
        let columns = lines[i].components(separatedBy: ",")
        if columns.count >= 4 {
            let name = columns[1].trimmingCharacters(in: .whitespaces)
            let dept = columns[2].trimmingCharacters(in: .whitespaces)
            let salaryString = columns[3].trimmingCharacters(in: .whitespaces)
            let salary = Double(salaryString) ?? 0.0
            names.append(name)
            departments.append(dept)
            salaries.append(salary)
        }
    }

    var deptTotals: [String: Double] = [:]
    var deptCounts: [String: Int] = [:]
    for i in 0..<departments.count {
        let dept = departments[i]
        let salary = salaries[i]
        deptTotals[dept, default: 0.0] += salary
        deptCounts[dept, default: 0] += 1
    }

    let sortedDepts = deptTotals.keys.sorted()

    var highestPaidName = ""
    var highestPaidSalary: Double = -1.0
    for i in 0..<names.count {
        if salaries[i] > highestPaidSalary {
            highestPaidSalary = salaries[i]
            highestPaidName = names[i]
        }
    }

    let totalBudget = salaries.reduce(0.0, +)

    print("=== Salary Report ===")
    print("")
    print("Average Salary by Department:")
    for dept in sortedDepts {
        let avg = deptTotals[dept]! / Double(deptCounts[dept]!)
        print("  \(dept): \(formatCurrency(value: avg, decimals: 2))")
    }
    print("")
    print("Highest Paid: \(highestPaidName) (\(formatCurrency(value: highestPaidSalary, decimals: 0)))")
    print("")
    print("Departments with >2 employees:")
    let filteredDepts = deptCounts.filter { $0.value > 2 }.keys.sorted()
    for dept in filteredDepts {
        print("  \(dept) (\(deptCounts[dept]!) employees)")
    }
    print("")
    print("Total Budget: \(formatCurrency(value: totalBudget, decimals: 0))")
}

