fn format_int_with_commas(s: &str) -> String {
    if s.is_empty() {
        return "".to_string();
    }
    let is_negative = s.starts_with('-');
    let abs_s = if is_negative { &s[1..] } else { s };

    let bytes = abs_s.as_bytes();
    let len = bytes.len();
    let mut res = String::new();
    for i in 0..len {
        if i > 0 && (len - i) % 3 == 0 {
            res.push(',');
        }
        res.push(bytes[i] as char);
    }
    if is_negative {
        format!("-{}", res)
    } else {
        res
    }
}

fn format_comma_float(n: f64) -> String {
    let s = format!("{:.2}", n);
    let parts: Vec<&str> = s.split('.').collect();
    let int_part = parts[0];
    let dec_part = parts[1];

    if int_part.starts_with('-') {
        let abs_int = &int_part[1..];
        format!("-{}", format_int_with_commas(abs_int)) + &format!(".{}", dec_part)
    } else {
        format!("{}.{}", format_int_with_commas(int_part), dec_part)
    }
}

