    let file = match File::open(path) {
        Ok(f) => f,
        Err(_) => return,
    };
    let reader = BufReader::new(file);
    let mut lines = reader.lines();

    // Skip header
    let _ = lines.next();

    let mut dept_sums: HashMap<String, i64> = HashMap::new();
    let mut dept_counts: HashMap<String, usize> = HashMap::new();
    let mut total_budget: i64 = 0;
    let mut highest_paid_salary: i64 = i64::MIN;
    let mut highest_paid_name = String::new();

    for line in lines {
        if let Ok(l) = line {
            let parts: Vec<&str> = l.split(',').collect();
            if parts.len() >= 4 {
                let name = parts[1].trim().to_string();
                let dept = parts[2].trim().to_string();
                let salary: i64 = parts[3].trim().parse().unwrap_or(0);

                *dept_sums.entry(dept.clone()).or_insert(0) += salary;
                *dept_counts.entry(dept).or_insert(0) += 1;

                total_budget += salary;

                if salary > highest_paid_salary {
                    highest_paid_salary = salary;
                    highest_paid_name = name;
                }
            }
        }
    }

    println!("=== Salary Report ===");
    println!();
