    let mut sorted_depts: Vec<_> = dept_sums.keys().collect();
    sorted_depts.sort();
    for dept in sorted_depts {
        let sum = dept_sums.get(dept).unwrap();
        let count = dept_counts.get(dept).unwrap();
        let avg = *sum as f64 / *count as f64;
        println!("  {}: ${}", dept, format_comma_float(avg));
    }

    println!();
    println!("Highest Paid: {} (${})", highest_paid_name, format_int_with_commas(&highest_paid_salary.to_string()));

    println!();
