    let mut sorted_dept_names: Vec<_> = dept_counts.keys().collect();
    sorted_dept_names.sort();
    for dept in sorted_dept_names {
        let count = dept_counts.get(dept).unwrap();
        if *count > 2 {
            println!("  {} ({} employees)", dept, count);
        }
    }

    println!();
    println!("Total Budget: ${}", format_int_with_commas(&total_budget.to_string()));
}

