use std::fs::File;
use std::io::{BufRead, BufReader};
use std::collections::{BTreeMap, BTreeSet, HashMap};

fn main() {
    let path = "/tmp/…/app.log";
    let file = match File::open(path) {
        Ok(f) => f,
        Err(_) => return,
    };
    let reader = BufReader::new(file);

    let mut level_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_component_counts: HashMap<String, usize> = HashMap::new();
    let mut unique_error_messages: BTreeSet<String> = BTreeSet::new();
    let mut hour_counts = [0usize; 24];

    for line_result in reader.lines() {
        let line = match line_result {
            Ok(l) => l,
            Err(_) => continue,
        };
        if line.is_empty() {
            continue;
        }

        let bracket_end = match line.find(']') {
            Some(idx) => idx,
            None => continue,
        };

        if bracket_end + 2 >= line.len() {
            continue;
        }

        let level_part = &line[bracket_end + 2..];

        let paren_start = match level_part.find(" (") {
            Some(idx) => idx,
            None => continue,
        };
        let paren_end = match level_part.find(") - ") {
            Some(idx) => idx,
            None => continue,
        };

        let level = &level_part[..paren_start];
        let component = &level_part[paren_start + 2..paren_end];
        let message = &level_part[paren_end + 4..];

