use std::collections::BTreeMap;
use std::fs;

#[derive(Debug, Clone, PartialEq, Eq)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(String),
    String(String),
    Array(Vec<JsonValue>),
    Object(BTreeMap<String, JsonValue>),
}

struct Parser<'a> {
    chars: std::iter::Peekable<std::str::Chars<'a>>,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Self {
            chars: s.chars().peekable(),
        }
    }

    fn consume_whitespace(&mut self) {
        while let Some(&c) = self.chars.peek() {
            if c.is_whitespace() {
                self.chars.next();
            } else {
                break;
            }
        }
    }

    fn parse_value(&mut self) -> JsonValue {
        self.consume_whitespace();
        let c = match self.chars.peek() {
            Some(&c) => c,
            None => return JsonValue::Null,
        };
        match c {
            '{' => self.parse_object(),
            '[' => self.parse_array(),
            '"' => self.parse_string(),
            't' | 'f' => self.parse_bool(),
            'n' => self.parse_null(),
            _ => self.parse_number(),
        }
    }

    fn parse_object(&mut self) -> JsonValue {
        self.chars.next(); // consume '{'
        let mut map = BTreeMap::new();
        self.consume_whitespace();
        if let Some(&'}') = self.chars.peek() {
            self.chars.next();
            return JsonValue::Object(map);
        }
        loop {
            let key = self.parse_string();
            self.consume_whitespace();
            if let Some(':') = self.chars.next() {
                // consume ':'
            }
            let val = self.parse_value();
            map.insert(key, val);
            self.consume_whitespace();
            if let Some(&'}') = self.chars.peek() {
                self.chars.next();
                break;
            }
            if let Some(&',') = self.chars.peek() {
                self.chars.next();
            }
        }
        JsonValue::Object(map)
    }

    fn parse_array(&mut self) -> JsonValue {
        self.chars.next(); // consume '['
        let mut arr = Vec::new();
        self.consume_whitespace();
        if let Some(&']') = self.chars.peek() {
            self.chars.next();
            return JsonValue::Array(arr);
        }
        loop {
            let val = self.parse_value();
            arr.push(val);
            self.consume_whitespace();
            if let Some(&']') = self.chars.peek() {
                self.chars.next();
                break;
            }
            if let Some(&',') = self.chars.peek() {
                self.chars.next();
            }
        }
        JsonValue::Array(arr)
    }

    fn parse_string(&mut self) -> JsonValue {
        self.chars.next(); // consume '"'
        let mut res = String::new();
        while let Some(c) = self.chars.next() {
            if c == '"' {
                return JsonValue::String(res);
            }
            if c == '\\' {
                if let Some(esc) = self.chars.next() {
                    match esc {
                        'n' => res.push('\n'),
                        'r' => res.push('\r'),
                        't' => res.push('\t'),
                        '\\' => res.push('\\'),
                        '"' => res.push('"'),
                        _ => res.push(esc),
                    }
                }
            } else {
                res.push(c);
            }
        }
        JsonValue::String(res)
    }

    fn parse_bool(&mut self) -> JsonValue {
        let c = self.chars.next().unwrap();
        if c == 't' {
            for _ in 0..3 {
                self.chars.next();
            }
            JsonValue::Bool(true)
        } else {
            for _ in 0..4 {
                self.chars.next();
            }
            JsonValue::Bool(false)
        }
    }

    fn parse_null(&mut self) -> JsonValue {
        for _ in 0..3 {
            self.chars.next();
        }
        JsonValue::Null
    }

    fn parse_number(&mut self) -> JsonValue {
        let mut s = String::new();
        while let Some(&c) = self.chars.peek() {
            if c.is_ascii_digit() || "-.+eE".contains(c) {
                s.push(self.chars.next().unwrap());
            } else {
                break;
            }
        }
        JsonValue::Number(s)
    }
}

fn merge(a: JsonValue, b: JsonValue) -> JsonValue {
    match (a, b) {
        (JsonValue::Object(mut map_a), JsonValue::Object(map_b)) => {
            for (k, v) in map_b {
                if let Some(existing) = map_a.remove(&k) {
                    map_a.insert(k, merge(existing, v));
                } else {
                    map_a.insert(k, v);
                }
            }
            JsonValue::Object(map_a)
        }
        (JsonValue::Array(mut arr_a), JsonValue::Array(arr_b)) => {
            arr_a.extend(arr_b);
            let mut seen = Vec::new();
            for item in arr_a {
                if !seen.contains(&item) {
                    seen.push(item);
                }
            }
            JsonValue::Array(seen)
        }
        (_, b) => b,
    }
}

fn serialize(val: &JsonValue, indent: usize) -> String {
    let space = "  ".repeat(indent);
    match val {
        JsonValue::Null => "null".to_string(),
        JsonValue::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
        JsonValue::Number(n) => n.clone(),
        JsonValue::String(s) => format!("\"{}\"", s),
        JsonValue::Array(arr) => {
            if arr.is_empty() {
                return "[]".to_string();
            }
            let mut res = String::from("[\n");
            let next_indent = "  ".repeat(indent + 1);
            for (i, item) in arr.iter().enumerate() {
                res.push_str(&next_indent);
                res.push_str(&serialize(item, indent + 1));
                if i < arr.len() - 1 {
                    res.push(',');
                }
                res.push('\n');
            }
            res.push_str(&space);
            res.push(']');
            res
        }
        JsonValue::Object(map) => {
            if map.is_empty() {
                return "{}".to_string();
            }
            let mut res = String::from("{\n");
            let next_indent = "  ".repeat(indent + 1);
            let keys: Vec<_> = map.keys().collect();
            for (i, &key) in keys.iter().enumerate() {
                res.push_str(&next_indent);
                res.push_str(&format!("\"{}\": ", key));
                res.push_str(&serialize(&map[key], indent + 1));
                if i < keys.len() - 1 {
                    res.push(',');
                }
                res.push('\n');
            }
            res.push_str(&space);
            res.push('}');
            res
        }
    }
}

