import Foundation

func areEqual(_ lhs: Any, _ rhs: Any) -> Bool {
    if let lDict = lhs as? [String: Any], let rDict = rhs as? [String: Any] {
        return (lDict as NSDictionary).isEqual(rDict)
    }
    if let lArr = lhs as? [Any], let rArr = rhs as? [Any] {
        if lArr.count != rArr.count { return false }
        for i in 0..<lArr.count {
            if !areEqual(lArr[i], rArr[i]) { return false }
        }
        return true
    }
    let l = lhs as? AnyHashable
    let r = rhs as? AnyHashable
    if let l = l, let r = r {
        return l == r
    }
    return false
}

func merge(a: Any, b: Any) -> Any {
    if let aDict = a as? [String: Any], let bDict = b as? [String: Any] {
        var res = aDict
        for (key, bVal) in bDict {
            if let aVal = aDict[key] {
                res[key] = merge(a: aVal, b: bVal)
            } else {
                res[key] = bVal
            }
        }
        return res
    } else if let aArr = a as? [Any], let bArr = b as? [Any] {
        var res = aArr
        for bVal in bArr {
            var exists = false
            for aVal in res {
                if areEqual(aVal, bVal) {
                    exists = true
                    break
                }
            }
            if !exists {
                res.append(bVal)
            }
        }
        return res
    } else {
        return b
    }
}

func reIndent(_ jsonString: String) -> String {
    let lines = jsonString.components(separatedBy: .newlines)
    var result = [String]()
    for line in lines {
        let spaces = line.prefix(while: { $0 == " " }).count
        let trimmed = line.dropFirst(spaces)
        if trimmed.isEmpty {
            result.append("")
            continue
        }
        let newIndentCount = spaces / 2
        let newIndent = String(repeating: " ", count: newIndentCount)
        result.append(newIndent + String(trimmed))
    }
    return result.joined(separator: "\n")
}

