    static class JsonSerializer {
        public static String serialize(Object obj) {
            return serialize(obj, 0);
        }

        @SuppressWarnings("unchecked")
        private static String serialize(Object obj, int indent) {
            String spacing = repeat("  ", indent);
            String nextSpacing = repeat("  ", indent + 1);

            if (obj == null) return "null";
            if (obj instanceof String) return "\"" + ((String) obj).replace("\"", "\\\"") + "\"";
            if (obj instanceof Boolean || obj instanceof Long) return obj.toString();
            if (obj instanceof Double) {
                Double d = (Double) obj;
                if (d == (long) d) return String.valueOf((long) d);
                else return String.valueOf(d);
            }
            if (obj instanceof Map) {
                TreeMap<String, Object> map = new TreeMap<>((Map<String, Object>) obj);
                StringBuilder sb = new StringBuilder("{\n");
                Iterator<Map.Entry<String, Object>> it = map.entrySet().iterator();
                while (it.hasNext()) {
                    Map.Entry<String, Object> entry = it.next();
                    sb.append(nextSpacing).append("\"").append(entry.getKey()).append("\": ");
                    sb.append(serialize(entry.getValue(), indent + 1));
                    if (it.hasNext()) sb.append(",");
                    sb.append("\n");
                }
                sb.append(spacing).append("}");
                return sb.toString();
            }
            if (obj instanceof List) {
                List<Object> list = (List<Object>) obj;
                StringBuilder sb = new StringBuilder("[\n");
                for (int i = 0; i < list.size(); i++) {
                    sb.append(nextSpacing).append(serialize(list.get(i), indent + 1));
                    if (i < list.size() - 1) sb.append(",");
                    sb.append("\n");
                }
                sb.append(spacing).append("]");
                return sb.toString();
            }
            return obj.toString();
        }

        private static String repeat(String s, int count) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < count; i++) sb.append(s);
            return sb.toString();
        }
    }
