import * as fs from 'fs';

const filePath = '/tmp/…/app.log';

try {
  const content = fs.readFileSync(filePath, 'utf8');
  const lines = content.split(/\r?\n/);

  const levelCounts: Record<string, number> = {};
  const componentErrorCounts: Record<string, number> = {};
  const errorMessages = new Set<string>();
  const hourCounts: Record<string, number> = {};

  for (const line of lines) {
    if (!line.trim()) continue;

    // Format: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
    const match = line.match(/^\[(\d{4}-\d{2}-\d{2} (\d{2}):\d{2}:\d{2})\] (\w+) \(([^)]+)\) - (.*)$/);
    if (match) {
      const [, , hour, level, component, message] = match;

      // 1. Level counts
      levelCounts[level] = (levelCounts[level] || 0) + 1;

      // 2. Error-specific counts
      if (level === 'ERROR') {
        componentErrorCounts[component] = (componentErrorCounts[component] || 0) + 1;
        errorMessages.add(message);
      }

      // 3. Hour counts
      hourCounts[hour] = (hourCounts[hour] || 0) + 1;
    }
  }

  // Sort Level names alphabetically
  const sortedLevels = Object.keys(levelCounts).sort();

  // Find component with most errors
  let maxErrorComponent = "";
  let maxErrorCount = 0;
  for (const comp in componentErrorCounts) {
    if (componentErrorCounts[comp] > maxErrorCount) {
      maxErrorCount = componentErrorCounts[comp];
      maxErrorComponent = comp;
    }
  }

  // Sort error messages alphabetically
  const sortedErrorMessages = Array.from(errorMessages).sort();

  // Find busiest hour
  let maxHour = "";
  let maxHourCount = 0;
  for (const hour in hourCounts) {
    if (hourCounts[hour] > maxHourCount) {
      maxHourCount = hourCounts[hour];
      maxHour = hour;
    }
  }

  // Output
  process.stdout.write("=== Log Analysis ===\n\n");

  process.stdout.write("Entries by Level:\n");
  for (const level of sortedLevels) {
    process.stdout.write(`  ${level}: ${levelCounts[level]}\n`);
  }
  process.stdout.write("\n");

  process.stdout.write(`Component with Most Errors: ${maxErrorComponent} (${maxErrorCount} errors)\n\n`);

  process.stdout.write("Unique Error Messages:\n");
  for (const msg of sortedErrorMessages) {
    process.stdout.write(`  - ${msg}\n`);
  }
  process.stdout.write("\n");

  process.stdout.write(`Busiest Hour: ${maxHour}:00 (${maxHourCount} entries)\n`);

} catch (err) {
  // Silent catch for runtime environment consistency
}

