function solve(): void {
  const filePath = '/tmp/…/graph.json';
  let data: GraphData;

  try {
    const content = fs.readFileSync(filePath, 'utf8');
    data = JSON.parse(content);
  } catch (err) {
    return;
  }

  const adj = new Map<string, { node: string; weight: number }[]>();
  for (const node of data.nodes) {
    adj.set(node, []);
  }

  for (const edge of data.edges) {
    if (adj.has(edge.from) && adj.has(edge.to)) {
      adj.get(edge.from)!.push({ node: edge.to, weight: edge.weight });
      adj.get(edge.to)!.push({ node: edge.from, weight: edge.weight });
    }
  }

  const distances = new Map<string, number>();
  for (const node of data.nodes) {
    distances.set(node, Infinity);
  }

  const pq = new MinHeap();
  const source = 'A';

  if (distances.has(source)) {
    distances.set(source, 0);
    pq.push({ node: source, dist: 0 });
  }

  while (pq.size() > 0) {
    const current = pq.pop()!;
    const u = current.node;
    const d = current.dist;

    if (d > (distances.get(u) ?? Infinity)) continue;

    const neighbors = adj.get(u) || [];
    for (const neighbor of neighbors) {
      const v = neighbor.node;
      const weight = neighbor.weight;
      const newDist = d + weight;

      if (newDist < (distances.get(v) ?? Infinity)) {
        distances.set(v, newDist);
        pq.push({ node: v, dist: newDist });
      }
    }
  }

  process.stdout.write('=== Shortest Paths from A ===\n\n');
  const sortedNodes = [...data.nodes].sort();
  for (const node of sortedNodes) {
    const dist = distances.get(node);
    process.stdout.write(`A -> ${node}: ${dist}\n`);
  }
}

