use std::io::{Read, Write};
use std::net::TcpStream;

struct Product {
    name: String,
    price: f64,
}

fn main() {
    let mut stream = match TcpStream::connect("127.0.0.1:18924") {
        Ok(s) => s,
        Err(_) => return,
    };

    let request = "GET /api/products HTTP/1.1\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n";
    if let Err(_) = stream.write_all(request.as_bytes()) {
        return;
    }

    let mut response = String::new();
    if let Err(_) = stream.read_to_string(&mut response) {
        return;
    }

    let body = if let Some(pos) = response.find("\r\n\r\n") {
        &response[pos + 4..]
    } else {
        ""
    };

    let mut products = Vec::new();
    let mut current_pos = 0;

    while let Some(start_idx) = body[current_pos..].find('{') {
        let absolute_start = current_pos + start_idx;
        if let Some(end_idx) = body[absolute_start..].find('}') {
            let absolute_end = absolute_start + end_idx;
            let object_str = &body[absolute_start..=absolute_end];

            let mut name = String::new();
            let mut price = 0.0;
            let mut found_name = false;
            let mut found_price = false;

            if let Some(n_idx) = object_str.find("\"name\"") {
                let after_name = &object_str[n_idx + 6..];
                if let Some(colon_idx) = after_name.find(':') {
                    let after_colon = &after_name[colon_idx + 1..];
                    if let Some(q1_idx) = after_colon.find('"') {
                        let val_start = q1_idx + 1;
                        if let Some(q2_idx) = after_colon[val_start..].find('"') {
                            name = after_colon[val_start..val_start + q2_idx].to_string();
                            found_name = true;
                        }
                    }
                }
            }

            if let Some(p_idx) = object_str.find("\"price\"") {
                let after_price = &object_str[p_idx + 7..];
                if let Some(colon_idx) = after_price.find(':') {
                    let after_colon = &after_price[colon_idx + 1..];
                    let mut price_str = String::new();
                    let mut found_digit = false;
                    for c in after_colon.trim_start().chars() {
                        if c.is_digit(10) || c == '.' || c == '-' {
                            price_str.push(c);
                            found_digit = true;
                        } else if found_digit {
                            break;
                        }
                    }
                    if let Ok(p) = price_str.parse::<f64>() {
                        price = p;
                        found_price = true;
                    }
                }
            }

            if found_name && found_price {
                products.push(Product { name, price });
            }
            current_pos = absolute_end + 1;
        } else {
            break;
        }
    }

    let mut filtered: Vec<_> = products.into_iter()
        .filter(|p| p.price > 50.0)
        .collect();

    filtered.sort_by(|a, b| a.name.cmp(&b.name));

    println!("=== Filtered Products (price > $50.00) ===");
    println!();
    for p in &filtered {
        println!("{}: ${:.2}", p.name, p.price);
    }
    println!();
    println!("Count: {}", filtered.len());
    let total: f64 = filtered.iter().map(|p| p.price).sum();
    println!("Total: ${:.2}", total);
}

#include <stdio.h>
