typedef struct {
    char name[128];
    int count;
} LevelEntry;

typedef struct {
    char name[128];
    int count;
} ComponentEntry;

int compare_level(const void *a, const void *b) {
    return strcmp(((LevelEntry *)a)->name, ((LevelEntry *)b)->name);
}

int compare_messages(const void *a, const void *b) {
    return strcmp(*(const char **)a, *(const char **)b);
}

char *my_strdup(const char *s) {
    size_t len = strlen(s) + 1;
    char *new_s = malloc(len);
    if (new_s) strcpy(new_s, s);
    return new_s;
}

int main(void) {
    const char *filename = "/tmp/…/app.log";
    FILE *fp = fopen(filename, "r");
    if (!fp) return 0;

    LevelEntry *levels = malloc(sizeof(LevelEntry) * 1000);
    int level_count = 0;

    ComponentEntry *components = malloc(sizeof(ComponentEntry) * 1000);
    int component_count = 0;

    char **error_messages = malloc(sizeof(char *) * 10000);
    int error_msg_count = 0;

    int hour_counts[24] = {0};

    char line[8192];
    while (fgets(line, sizeof(line), fp)) {
        int hour = 0;
        if (sscanf(line, "[%*d-%*d-%*d %d", &hour) != 1) continue;

        char *bracket_end = strchr(line, ']');
        if (!bracket_end) continue;
        char *paren_start = strchr(bracket_end, '(');
        if (!paren_start) continue;
        char *paren_end = strchr(paren_start, ')');
        if (!paren_end) continue;
        char *dash_start = strstr(paren_end, ") - ");
        if (!dash_start) continue;
        char *message_start = dash_start + 4;

        int level_len = (int)(paren_start - (bracket_end + 2));
        char level[128] = {0};
        if (level_len > 0) {
            if (level_len >= 128) level_len = 127;
            strncpy(level, bracket_end + 2, level_len);
            int len = (int)strlen(level);
            while (len > 0 && level[len - 1] == ' ') {
                level[--len] = '\0';
            }
        }

        int comp_len = (int)(paren_end - (paren_start + 1));
        char component[128] = {0};
        if (comp_len > 0) {
            if (comp_len >= 128) comp_len = 127;
            strncpy(component, paren_start + 1, comp_len);
            int len = (int)strlen(component);
            while (len > 0 && component[len - 1] == ' ') {
                component[--len] = '\0';
            }
        }

        char *nl = strchr(message_start, '\n');
        if (nl) *nl = '\0';
        char *rl = strchr(message_start, '\r');
        if (rl) *rl = '\0';

        // 1. Update Level Counts
        int found_level = 0;
        for (int i = 0; i < level_count; i++) {
            if (strcmp(levels[i].name, level) == 0) {
                levels[i].count++;
                found_level = 1;
                break;
            }
        }
        if (!found_level) {
            strcpy(levels[level_count].name, level);
            levels[level_count].count = 1;
            level_count++;
        }

        // 2. Update Component/Message Counts (if ERROR)
        if (strcmp(level, "ERROR") == 0) {
            int found_comp = 0;
            for (int i = 0; i < component_count; i++) {
                if (strcmp(components[i].name, component) == 0) {
                    components[i].count++;
                    found_comp = 1;
                    break;
                }
            }
            if (!found_comp) {
                strcpy(components[component_count].name, component);
                components[component_count].count = 1;
                component_count++;
            }
            error_messages[error_msg_count++] = my_strdup(message_start);
        }

        // 3. Update Hour Counts
        hour_counts[hour]++;
    }
    fclose(fp);

    printf("=== Log Analysis ===\n\n");

    printf("Entries by Level:\n");
    qsort(levels, level_count, sizeof(LevelEntry), compare_level);
    for (int i = 0; i < level_count; i++) {
        printf("  %s: %d\n", levels[i].name, levels[i].count);
    }
    printf("\n");

    int max_comp_idx = -1;
    int max_comp_val = -1;
    for (int i = 0; i < component_count; i++) {
        if (components[i].count > max_comp_val) {
            max_comp_val = components[i].count;
            max_comp_idx = i;
        }
    }
    if (max_comp_idx != -1) {
        printf("Component with Most Errors: %s (%d errors)\n", components[max_comp_idx].name, max_comp_val);
    } else {
        printf("Component with Most Errors: \n");
    }
    printf("\n");

    printf("Unique Error Messages:\n");
    if (error_msg_count > 0) {
        qsort(error_messages, error_msg_count, sizeof(char *), compare_messages);
        for (int i = 0; i < error_msg_count; i++) {
            if (i == 0 || strcmp(error_messages[i], error_messages[i - 1]) != 0) {
                printf("  - %s\n", error_messages[i]);
            }
        }
    }
    printf("\n");

    int max_hour = 0;
    int max_hour_val = -1;
    for (int i = 0; i < 24; i++) {
        if (hour_counts[i] > max_hour_val) {
            max_hour_val = hour_counts[i];
            max_hour = i;
        }
    }
    printf("Busiest Hour: %02d:00 (%d entries)\n", max_hour, max_hour_val == -1 ? 0 : max_hour_val);

    // Cleanup
    for (int i = 0; i < error_msg_count; i++) free(error_messages[i]);
    free(error_messages);
    free(levels);
    free(components);

    return 0;
}

