struct PriorityQueue<Element> {
    private var elements: [Element]
    private let priorityFunction: (Element, Element) -> Bool

    init(priorityFunction: @escaping (Element, Element) -> Bool) {
        self.elements = []
        self.priorityFunction = priorityFunction
    }

    var isEmpty: Bool { return elements.isEmpty }

    mutating func enqueue(_ element: Element) {
        elements.append(element)
        siftUp(elements.count - 1)
    }

    mutating func dequeue() -> Element? {
        guard !elements.isEmpty else { return nil }
        if elements.count == 1 { return elements.removeFirst() }
        let element = elements[0]
        elements[0] = elements.removeLast()
        siftDown(0)
        return element
    }

    private mutating func siftUp(index: Int) {
        var child = index
        while child > 0 {
            let parent = (child - 1) / 2
            if priorityFunction(elements[child], elements[parent]) {
                elements.swapAt(child, parent)
                child = parent
            } else {
                break
            }
        }
    }

    private mutating func siftDown(index: Int) {
        var parent = index
        while true {
            let leftChild = 2 * parent + 1
            let rightChild = 2 * parent + 2
            var candidate = parent

            if leftChild < elements.count && priorityFunction(elements[leftChild], elements[candidate]) {
                candidate = leftChild
            }
            if rightChild < elements.count && priorityFunction(elements[rightChild], elements[candidate]) {
                candidate = rightChild
            }
            if candidate == parent {
                break
            }
            elements.swapAt(parent, candidate)
            parent = candidate
        }
    }
}

