import Foundation

let rootPath = "/tmp/…/project_tree"
let rootURL = URL(fileURLWithPath: rootPath)

struct FileInfo {
    let relativePath: String
    let lines: Int
    let characters: Int
}

var groups: [String: [FileInfo]] = [:]
var totalFiles = 0
var totalLines = 0
var totalChars = 0

let fileManager = FileManager.default
let enumerator = fileManager.enumerator(at: rootURL, includingSubpaths: true, options: [.skipsPackageDescendants])

while let url = enumerator?.nextObject() as? URL {
    let isDir = (try? url.resourceValues(forKeys: [.isDirectoryKey]).isDirectory) ?? false
    if isDir || url.path == rootURL.path {
        continue
    }

    let filePath = url.path
    let rootPathStr = rootURL.path
    let prefix = rootPathStr.hasSuffix("/") ? rootPathStr : rootPathStr + "/"
    let relPath = String(filePath.dropFirst(prefix.count))
    let ext = url.pathExtension.isEmpty ? "" : "." + url.pathExtension

    do {
        let data = try Data(contentsOf: url)
        let bytes = data.count
        let content = String(data: data, encoding: .utf8)

        let linesCount: Int
        if let content = content {
            if content.isEmpty {
                linesCount = 0
            } else {
                let components = content.components(separatedBy: "\n")
                linesCount = content.hasSuffix("\n") ? components.count - 1 : components.count
            }
        } else {
            linesCount = 0
        }

        let info = FileInfo(relativePath: relPath, lines: linesCount, characters: bytes)

        if groups[ext] == nil {
            groups[ext] = []
        }
        groups[ext]?.append(info)

        totalFiles += 1
        totalLines += linesCount
        totalChars += bytes
    } catch {
        continue
    }
}

let sortedExtensions = groups.keys.sorted()

print("=== File Tree Analysis ===")
print("")

for ext in sortedExtensions {
    let files = groups[ext]!.sorted(by: { $0.relativePath < $1.relativePath })
    let extFilesCount = files.count
    let extLines = files.reduce(0) { $0 + $1.lines }
    let extChars = files.reduce(0) { $0 + $1.characters }

    print("Extension: \(ext)")
    print("  Files: \(extFilesCount)")
    print("  Total Lines: \(extLines)")
    print("  Total Characters: \(extChars)")
    for file in files {
        print("    \(file.relativePath): \(file.lines) lines, \(file.characters) chars")
    }
}

print("")
print("Total: \(totalFiles) files, \(totalLines) lines, \(totalChars) characters")

