use std::collections::BTreeMap;
use std::fs;
use std::path::Path;

struct FileInfo {
    rel_path: String,
    lines: usize,
    chars: usize,
}

fn walk(dir: &Path, base: &Path, map: &mut BTreeMap<String, Vec<FileInfo>>) -> std::io::Result<()> {
    if dir.is_dir() {
        for entry in fs::read_dir(dir)? {
            let entry = entry?;
            let path = entry.path();
            let metadata = fs::symlink_metadata(&path)?;

            if metadata.is_dir() {
                walk(&path, base, map)?;
            } else if metadata.is_file() {
                let rel_path = path.strip_prefix(base).unwrap_or(&path).to_string_lossy().into_owned();
                let ext = path
                    .extension()
                    .and_then(|s| s.to_str())
                    .map(|s| format!(".{}", s))
                    .unwrap_or_else(|| "".to_string());

                let content = fs::read(&path).unwrap_or_default();
                let chars = content.len();
                let lines = if content.is_empty() {
                    0
                } else {
                    let mut count = 0;
                    for &b in &content {
                        if b == b'\n' {
                            count += 1;
                        }
                    }
                    if content.last() != Some(&b'\n') {
                        count += 1;
                    }
                    count
                };

                map.entry(ext).or_insert_with(Vec::new).push(FileInfo {
                    rel_path,
                    lines,
                    chars,
                });
            }
        }
    }
    Ok(())
}

fn main() {
    let base_path = Path::new("/tmp/…/project_tree");
    let mut extension_map: BTreeMap<String, Vec<FileInfo>> = BTreeMap::new();

    let _ = walk(base_path, base_path, &mut extension_map);

    println!("=== File Tree Analysis ===");
    println!();

    let mut total_files = 0;
    let mut total_lines = 0;
    let mut total_chars = 0;

    for files in extension_map.values() {
        total_files += files.len();
        for f in files {
            total_lines += f.lines;
            total_chars += f.chars;
        }
    }

    for (ext, mut files) in extension_map {
        files.sort_by(|a, b| a.rel_path.cmp(&b.rel_path));

        let ext_files = files.len();
        let mut ext_lines = 0;
        let mut ext_chars = 0;

        println!("Extension: {}", ext);
        println!("  Files: {}", ext_files);

