#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/**
 * Executes a shell command and returns the output as a dynamically allocated string.
 * Trailing newlines and whitespace are stripped.
 */
char* run_cmd(const char* cmd) {
    char buffer[1024];
    char* res = NULL;
    FILE* fp = popen(cmd, "r");

    if (!fp) {
        return NULL;
    }

    if (fgets(buffer, sizeof(buffer), fp)) {
        size_t len = strlen(buffer);
        // Strip trailing newline, carriage return, and whitespace
        while (len > 0 && (buffer[len - 1] == '\n' || buffer[len - 1] == '\r' || buffer[len - 1] == ' ')) {
            buffer[--len] = '\0';
        }
        res = (char*)malloc(len + 1);
        if (res) {
            strcpy(res, buffer);
        }
    } else {
        // Handle empty output
        res = (char*)malloc(1);
        if (res) {
            res[0] = '\0';
        }
    }

    pclose(fp);
    return res;
}

int main(void) {
    // Capture command outputs
    char* hostname = run_cmd("hostname");
    char* os = run_cmd("uname -s");
    char* architecture = run_cmd("uname -m");
    char* username = run_cmd("whoami");

    // Output the JSON object with the specified keys and order
    printf("{\n");
    printf("  \"hostname\": \"%s\",\n", hostname ? hostname : "");
    printf("  \"os\": \"%s\",\n", os ? os : "");
    printf("  \"architecture\": \"%s\",\n", architecture ? architecture : "");
    printf("  \"username\": \"%s\"\n", username ? username : "");
    printf("}\n");

    // Clean up allocated memory
    free(hostname);
    free(os);
    free(architecture);
    free(username);

    return 0;
}

