def multiply(A, B):
    n = len(A)
    m = len(B[0])
    p = len(B)
    C = [[0 for _ in range(m)] for _ in range(n)]
    for i in range(n):
        for j in range(m):
            for k in range(p):
                C[i][j] += A[i][k] * B[k][j]
    return C

def determinant(M):
    if len(M) == 1:
        return M[0][0]
    if len(M) == 2:
        return M[0][0] * M[1][1] - M[0][1] * M[1][0]
    det = 0
    for c in range(len(M)):
        minor = [row[:c] + row[c+1:] for row in M[1:]]
        det += ((-1)**c) * M[0][c] * determinant(minor)
    return det

def main():
    A = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
    B = [[9, 8, 7], [6, 5, 4], [3, 2, 1]]

    C = multiply(A, B)
    det_C = determinant(C)

    print("=== Matrix Operations ===")
    print()
    print("Matrix A:")
    for row in A:
        print("  " + " ".join(f"{v:4d}" for v in row))
    print()
    print("Matrix B:")
    for row in B:
        print("  " + " ".join(f"{v:4d}" for v in row))
    print()
    print("A x B =")
    for row in C:
        print("  " + " ".join(f"{v:4d}" for v in row))
    print()
    print(f"Determinant: {det_C}")

