import * as fs from 'fs';
import * as path from 'path';

interface FileInfo {
  relPath: string;
  lines: number;
  chars: number;
}

function solve() {
  const rootDir = '/tmp/…/project_tree';
  const results = new Map<string, FileInfo[]>();
  let totalFiles = 0;
  let totalLines = 0;
  let totalChars = 0;

  function walk(dir: string) {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      if (entry.isSymbolicLink()) continue;

      if (entry.isDirectory()) {
        walk(fullPath);
      } else if (entry.isFile()) {
        const buffer = fs.readFileSync(fullPath);
        const content = buffer.toString('utf8');
        const lines = content === '' ? 0 : content.split(/\r?\n/).length;
        const chars = buffer.length;

        const ext = path.extname(fullPath);
        if (!results.has(ext)) {
          results.set(ext, []);
        }
        results.get(ext)!.push({
          relPath: path.relative(rootDir, fullPath).replace(/\\/g, '/'),
          lines,
          chars
        });
        totalFiles++;
        totalLines += lines;
        totalChars += chars;
      }
    }
  }

  if (fs.existsSync(rootDir)) {
    walk(rootDir);
  }

  const sortedExtensions = Array.from(results.keys()).sort();

  console.log('=== File Tree Analysis ===');
  console.log('');

  for (const ext of sortedExtensions) {
    const files = results.get(ext)!;
    files.sort((a, b) => a.relPath.localeCompare(b.relPath));

    const groupFiles = files.length;
    const groupLines = files.reduce((acc, f) => acc + f.lines, 0);
    const groupChars = files.reduce((acc, f) => acc + f.chars, 0);

    console.log(`Extension: ${ext}`);
    console.log(`  Files: ${groupFiles}`);
    console.log(`  Total Lines: ${groupLines}`);
    console.log(`  Total Characters: ${groupChars}`);
    for (const file of files) {
      console.log(`    ${file.relPath}: ${file.lines} lines, ${file.chars} chars`);
    }
  }

  console.log('');
  console.log(`Total: ${totalFiles} files, ${totalLines} lines, ${totalChars} characters`);
}

