import Foundation

let A = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
let B = [[9, 8, 7], [6, 5, 4], [3, 2, 1]]

func multiply(_ m1: [[Int]], _ m2: [[Int]]) -> [[Int]] {
    let rows = m1.count
    let cols = m2[0].count
    let common = m1[0].count
    var result = Array(repeating: Array(repeating: 0, count: cols), count: rows)
    for i in 0..<rows {
        for j in 0..<cols {
            for k in 0..<common {
                result[i][j] += m1[i][k] * m2[k][j]
            }
        }
    }
    return result
}

func determinant3x3(_ m: [[Int]]) -> Int {
    let a = m[0][0], b = m[0][1], c = m[0][2]
    let d = m[1][0], e = m[1][1], f = m[1][2]
    let g = m[2][0], h = m[2][1], i = m[2][2]
    return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g)
}

func printMatrix(_ m: [[Int]]) {
    for row in m {
        let rowString = row.map { String(format: "%4d", $0) }.joined(separator: " ")
        print("  \(rowString)")
    }
}

