#[derive(Eq, PartialEq)]
struct State {
    cost: u64,
    position: String,
}

impl Ord for State {
    fn cmp(&self, other: &Self) -> Ordering {
        other.cost.cmp(&self.cost)
            .then_with(|| self.position.cmp(&other.position))
    }
}

impl PartialOrd for State {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

fn extract_value(s: &str, key: &str) -> Option<String> {
    if let Some(start_idx) = s.find(key) {
        let val_start = start_idx + key.len();
        let remaining = &s[val_start..].trim_start();

        if remaining.starts_with('"') {
            if let Some(end_idx) = remaining[1..].find('"') {
                return Some(remaining[1..1+end_idx].to_string());
            }
        } else {
            let mut end_idx = 0;
            for c in remaining.chars() {
                if c.is_ascii_digit() || c == '.' || c == '-' {
                    end_idx += c.len_utfp();
                    // Using len_utf8() for safety, though ASCII is expected
                } else {
                    break;
                }
            }
            // Re-calculating end_idx using a more robust method for the numeric part
            let mut end_idx = 0;
            let mut chars_iter = remaining.chars();
            while let Some(c) = chars_iter.next() {
                if c.is_ascii_digit() || c == '.' || c == '-' {
                    end_idx += c.len_utf8();
                } else {
                    break;
                }
            }
            if end_idx > 0 {
                return Some(remaining[..end_idx].trim().to_string());
            }
        }
    }
    None
}

