const A: number[][] = [
  [1, 2, 3],
  [4, 5, 6],
  [7, 8, 9]
];

const B: number[][] = [
  [9, 8, 7],
  [6, 5, 4],
  [3, 2, 1]
];

function multiply(matrixA: number[][], matrixB: number[][]): number[][] {
  const size = matrixA.length;
  const result: number[][] = Array.from({ length: size }, () => Array(size).fill(0));
  for (let i = 0; i < size; i++) {
    for (let j = 0; j < size; j++) {
      for (let k = 0; k < size; k++) {
        result[i][j] += matrixA[i][k] * matrixB[k][j];
      }
    }
  }
  return result;
}

function determinant(M: number[][]): number {
  return M[0][0] * (M[1][1] * M[2][2] - M[1][2] * M[2][1]) -
         M[0][1] * (M[1][0] * M[2][2] - M[1][2] * M[2][0]) +
         M[0][2] * (M[1][0] * M[2][1] - M[1][1] * M[2][0]);
}

function printMatrix(matrix: number[][]): void {
  for (const row of matrix) {
    const formattedRow = "  " + row.map(v => v.toString().padStart(4)).join(" ");
    console.log(formattedRow);
  }
}

