int main(void) {
    int A[3][3] = {
        {1, 2, 3},
        {4, 5, 6},
        {7, 8, 9}
    };
    int B[3][3] = {
        {9, 8, 7},
        {6, 5, 4},
        {3, 2, 1}
    };
    int C[3][3] = {0};

    // Standard matrix multiplication (C = A x B)
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            for (int k = 0; k < 3; k++) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }

    // Determinant of a 3x3 matrix using Laplace expansion
    int det = C[0][0] * (C[1][1] * C[2][2] - C[1][2] * C[2][1]) -
              C[0][1] * (C[1][0] * C[2][2] - C[1][2] * C[2][0]) +
              C[0][2] * (C[1][0] * C[2][1] - C[1][1] * C[2][0]);

    // Output formatting
    printf("=== Matrix Operations ===\n\n");

    printf("Matrix A:\n");
    for (int i = 0; i < 3; i++) {
        printf("  %4d %4d %4d\n", A[i][0], A[i][1], A[i][2]);
    }

    printf("\nMatrix B:\n");
    for (int i = 0; i < 3; i++) {
        printf("  %4d %4d %4d\n", B[i][0], B[i][1], B[i][2]);
    }

    printf("\nA x B =\n");
    for (int i = 0; i < 3; i++) {
        printf("  %4d %4d %4d\n", C[i][0], C[i][1], C[i][2]);
    }

    printf("\nDeterminant: %d\n", det);

    return 0;
}

