        groups[group_idx].files = realloc(groups[group_idx].files, sizeof(FileInfo) * groups[group_idx].file_capacity);
    }
    groups[group_idx].files[groups[group_idx].file_count++] = *info;
    groups[group_idx].total_files++;
    groups[group_idx].total_lines += info->lines;
    groups[group_idx].total_chars += info->chars;
    total_files_all++;
    total_lines_all += info->lines;
    total_chars_all += info->chars;
}

