    }
    fclose(fp);
    FileInfo info;
    info.rel_path = strdup(rel_path);
    info.lines = lines;
    info.chars = chars;
    const char *last_slash = strrchr(rel_path, '/');
    const char *filename = (last_slash) ? last_slash + 1 : rel_path;
    const char *last_dot = strrchr(filename, '.');
    const char *ext = (last_dot) ? last_dot : "";
    add_file_to_group(ext, &info);
}

void walk_directory(const char *current_path, const char *current_rel_path) {
    DIR *dir = opendir(current_path);
    if (!dir) return;
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;
        char full_path[4096];
        snprintf(full_path, sizeof(full_path), "%s/%s", current_path, entry->d_name);
        struct stat st;
        if (lstat(full_path, &st) != 0) continue;
        char next_rel_path[4096];
        if (strlen(current_rel_path) == 0) strcpy(next_rel_path, entry->d_name);
        else snprintf(next_rel_path, sizeof(next_rel_path), "%s/%s", current_rel_path, entry->d_name);
        if (S_ISDIR(st.st_mode)) walk_directory(full_path, next_rel_path);
        else if (S_ISREG(st.st_mode)) process_file(full_path, next_rel_path);
    }
    closedir(dir);
}

