            snprintf(next_rel_path, sizeof(next_rel_path), "%s/%s", current_rel_path, entry->d_name);
        }

        if (S_ISDIR(st.st_mode)) {
            walk_directory(full_path, next_rel_path);
        } else if (S_ISREG(st.st_mode)) {
            process_file(full_path, next_rel_path);
        }
    }
    closedir(dir);
}

