// Parser functions
void skip_ws(const char **cursor) {
    while (**cursor && isspace(**cursor)) (*cursor)++;
}

char *parse_s(const char **cursor) {
    (*cursor)++; // skip "
    size_t cap = 128, len = 0;
    char *s = malloc(cap);
    while (**cursor && **cursor != '"') {
        if (**cursor == '\\') {
            (*cursor)++;
            char esc = **cursor;
            if (esc == '"') s[len++] = '"';
            else if (esc == '\\') s[len++] = '\\';
            else if (esc == 'n') s[len++] = '\n';
            else if (s[len] == 0) {} // handle
            else { // fallback
                s[len++] = '\\';
                s[len++] = esc;
            }
        } else {
            s[len++] = **cursor;
        }
        (*cursor)++;
        if (len + 1 >= cap) { cap *= 2; s = realloc(s, cap); }
    }
    if (**cursor == '"') (*cursor)++;
    s[len] = '\0';
    return s;
}

// Corrected string parser to handle escapes properly
char *parse_json_string(const char **cursor) {
    (*cursor)++; 
    size_t cap = 128, len = 0;
    char *s = malloc(cap);
    while (**cursor && **cursor != '"') {
        if (**cursor == '\\') {
            (*cursor)++;
            char c = **cursor;
            if (c == '"' || c == '\\' || c == '/' || c == 'b' || c == 'f' || c == 'n' || c == 'r' || c == 't') {
                if (c == '"') s[len++] = '"';
                else if (c == '\\') s[len++] = '\\';
                else if (c == 'b') s[len++] = '\b';
                else if (c == 'f') s[len++] = '\f';
                else if (c == 'n') s[len++] = '\n';
                else if (c == 'r') s[len++] = '\r';
                else if (c == 't') s[len++] = '\t';
                else s[len++] = c; 
            } else {
                s[len++] = '\\';
                s[len++] = c;
            }
        } else {
            s[len++] = **cursor;
        }
        (*cursor)++;
        if (len + 1 >= cap) { cap *= 2; s = realloc(s, cap); }
    }
    if (**cursor == '"') (*cursor)++;
    s[len] = '\0';
    return s;
}

json_node *parse_json(const char **cursor);

json_node *parse_json(const char **cursor) {
    skip_ws(cursor);
    json_node *node = malloc(sizeof(json_node));
    if (**cursor == '{') {
        node->type = T_OBJECT;
        node->u.object.size = 0;
        node->u.object.keys = NULL;
        node->u.object.values = NULL;
        (*cursor)++;
        skip_ws(cursor);
        while (**cursor && **cursor != '}') {
            char *key = parse_json_string(cursor);
            skip_ws(cursor);
            (*cursor)++; // skip :
            skip_ws(cursor);
            json_node *val = parse_json(cursor);
            a_add(node, key, val);
            skip_ws(cursor);
            if (**cursor == ',') (*cursor)++;
            skip_ws(cursor);
        }
        if (**cursor == '}') (*cursor)++;
    } else if (**cursor == '[') {
        node->type = T_ARRAY;
        node->u.array.size = 0;
        node->u.array.elements = NULL;
        (*cursor)++;
        skip_ws(cursor);

        while (**cursor && **cursor != ']') {
            json_node *val = parse_json(cursor);
            a_append(node, val);
            skip_ws(cursor);
            if (**cursor == ',') (*cursor)++;
            skip_ws(cursor);
        }
        if (**cursor == ']') (*cursor)++;
    } else if (**cursor == '"') {
        node->type = T_STRING;
        node->u.s_val = parse_json_string(cursor);
    } else {
        // Number, Bool, Null
        const char *start = *cursor;
        while (!isspace(**cursor) && **cursor != ',' && **cursor != '}' && **cursor != ']' && **cursor != ':' && **cursor != '{') {
            (*cursor)++;
        }
        size_t len = *cursor - start;
        char *buf = malloc(len + 1);
        strncpy(buf, start, len);
        buf[len] = '\0';
        if (strcmp(buf, "true") == 0) {
            node->type = T_BOOL;
            node->u.b_val = 1;
        } else if (strcmp(buf, "false") == 0) {
            node->type = T_BOOL;
            node->u.b_val = 0;
        } else if (strcmp(buf, "null") == 0) {
            node->type = T_NULL;
        } else {
            node->type = T_NUMBER;
            node->u.n_val = atof(buf);
        }
        free(buf);
    }
    return node;
}

