        while (**cursor && !isspace((unsigned char)**cursor) && **cursor != ',' && **cursor != '}' && **cursor != ']' && **cursor != ':' && **cursor != '{') {
            (*cursor)++;
        }
        size_t len = *cursor - start;
        char *buf = malloc(len + 1);
        strncpy(buf, start, len);
        buf[len] = '\0';
        if (strcmp(buf, "true") == 0) {
            node->type = T_BOOL;
            node->u.b_val = 1;
        } else if (strcmp(buf, "false") == 0) {
            node->type = T_BOOL;
            node->u.b_val = 0;
        } else if (strcmp(buf, "null") == 0) {
            node->type = T_NULL;
        } else {
            node->type = T_NUMBER;
            node->u.n_val = atof(buf);
        }
        free(buf);
    }
    return node;
}

