json_node *deep_copy(const json_node *src) {
    if (!src) return NULL;
    json_node *dest = malloc(sizeof(json_node));
    dest->type = src->type;
    if (src->type == T_OBJECT) {
        dest->u.object.size = src->u.object.size;
        dest->u.object.keys = malloc(sizeof(char *) * dest->u.object.size);
        dest->u.object.values = malloc(sizeof(json_node *) * dest->u.object.size);
        for (size_t i = 0; i < src->u.object.size; i++) {
            dest->u.object.keys[i] = strdup(src->u.object.keys[i]);
            dest->u.object.values[i] = deep_copy(src->u.object.values[i]);
        }
    } else if (src->type == T_ARRAY) {
        dest->u.array.size = src->u.array.size;
        dest->u.array.elements = malloc(sizeof(json_node *) * dest->u.array.size);
        for (size_t i = 0; i < src->u.array.size; i++) {
            dest->u.array.elements[i] = deep_copy(src->u.array.elements[i]);
        }
    } else if (src->type == T_STRING) {
        dest->u.s_val = strdup(src->u.s_val);
    } else if (src->type == T_NUMBER) {
        dest->u.n_val = src->u.n_val;
    } else if (src->type == T_BOOL) {
        dest->u.b_val = src->u.b_val;
    }
    return dest;
}

bool is_equal(const json_node *a, const json_node *b) {
    if (a->type != b->type) return false;
    if (a->type == T_NULL) return true;
    if (a->type == T_STRING) return strcmp(a->u.s_val, b->u.s_val) == 0;
    if (a->type == T_NUMBER) return fabs(a->u.n_val - b->u.n_val) < 1e-9;
    if (a->type == T_BOOL) return a->u.b_val == b->u.b_val;
    if (a->type == T_ARRAY) {
        if (a->u.array.size != b->u.array.size) return false;
        for (size_t i = 0; i < a->u.array.size; i++) {
            if (!is_equal(a->u.array.elements[i], b->u.array.elements[i])) return false;
        }
        return true;
    }
    if (a->type == T_OBJECT) {
        if (a->u.object.size != b->u.object.size) return false;
        for (size_t i = 0; i < a->u.object.size; i++) {
            bool found = false;
            for (size_t j = 0; j < b->u.object.size; j++) {
                if (strcmp(a->u.object.keys[i], b->u.object.keys[j]) == 0) {
                    if (is_equal(a->u.object.values[i], b->u.object.values[j])) {
                        found = true;
                        break;
                    } else return false;
                }
            }
            if (!found) return false;
        }
        return true;
    }
    return false;
}

int find_key_idx(json_node *obj, const char *key) {
    if (obj->type != T_OBJECT) return -1;
    for (size_t i = 0; i < obj->u.object.size; i++) {
        if (strcmp(obj->u.object.keys[i], key) == 0) return (int)i;
    }
    return -1;
}

void sort_object(json_node *obj) {
    if (obj->type != T_OBJECT || obj->u.object.size <= 1) return;
    for (size_t i = 0; i < obj->u.object.size - 1; i++) {
        for (size_t j = 0; j < obj->u.object.size - i - 1; j++) {
            if (strcmp(obj->u.object.keys[j], obj->u.object.keys[j + 1]) > 0) {
                char *tk = obj->u.object.keys[j];
                obj->u.object.keys[j] = obj->u.object.keys[j + 1];
                obj->u.object.keys[j + 1] = tk;
                json_node *tv = obj->u.object.values[j];
                obj->u.object.values[j] = obj->u.object.values[j + 1];
                obj->u.object.values[j + 1] = tv;
            }
        }
    }
}

