void skip_ws(const char **cursor) {
    while (**cursor && isspace((unsigned char)**cursor)) (*cursor)++;
}

char *parse_json_string(const char **cursor) {
    (*cursor)++;
    size_t cap = 128, len = 0;
    char *s = malloc(cap);
    while (**cursor && **cursor != '"') {
        if (**cursor == '\\') {
            (*cursor)++;
            char c = **cursor;
            if (c == '"' || c == '\\' || c == '/' || c == 'b' || c == 'f' || c == 'n' || c == 'r' || c == 't') {
                if (c == '"') s[len++] = '"';
                else if (c == '\\') s[len++] = '\\';
                else if (c == 'b') s[len++] = '\b';
                else if (c == 'f') s[len++] = '\f';
                else if (c == 'n') s[len++] = '\n';
                else if (c == 'r') s[len++] = '\r';
                else if (c == 't') s[len++] = '\t';
                else s[len++] = c;
            } else {
                s[len++] = '\\';
                s[len++] = c;
            }
        } else {
            s[len++] = **cursor;
        }
        (*cursor)++;
        if (len + 1 >= cap) { cap *= 2; s = realloc(s, cap); }
    }
    if (**cursor == '"') (*cursor)++;
    s[len] = '\0';
    return s;
}

json_node *parse_json(const char **cursor);

json_node *parse_json(const char **cursor) {
    skip_ws(cursor);
    json_node *node = malloc(sizeof(json_node));
    if (**cursor == '{') {
        node->type = T_OBJECT;
        node->u.object.size = 0;
        node->u.object.keys = NULL;
        node->u.object.values = NULL;
        (*cursor)++;
        skip_ws(cursor);
        while (**cursor && **cursor != '}') {
            char *key = parse_json_string(cursor);
            skip_ws(cursor);
            if (**cursor == ':') (*cursor)++;
            skip_ws(cursor);
            json_node *val = parse_json(cursor);
            a_add(node, key, val);
            skip_ws(cursor);
            if (**cursor == ',') (*cursor)++;
            skip_ws(cursor);
        }
        if (**cursor == '}') (*cursor)++;
    } else if (**cursor == '[') {
        node->type = T_ARRAY;
        node->u.array.size = 0;
        node->u.array.elements = NULL;
        (*cursor)++;
        skip_ws(cursor);
        while (**cursor && **cursor != ']') {
            json_node *val = parse_json(cursor);
            a_append(node, val);
            skip_ws(cursor);
            if (**cursor == ',') (*cursor)++;
            skip_ws(cursor);
        }
        if (**cursor == ']') (*cursor)++;
    } else if (**cursor == '"') {
        node->type = T_STRING;
        node->u.s_val = parse_json_string(cursor);
    } else {
        const char *start = *cursor;
        while (**cursor && !isspace((unsigned char)**cursor) && **cursor != ',' && **cursor != '}' && **cursor != ']' && **cursor != ':' && **cursor != '{') {
            (*cursor)++;
        }
        size_t len = *cursor - start;
        char *buf = malloc(len + 1);
        strncpy(buf, start, len);
        buf[len] = '\0';
        if (strcmp(buf, "true") == 0) {
            node->type = T_BOOL;
            node->u.b_val = 1;
        } else if (strcmp(buf, "false") == 0) {
            node->type = T_BOOL;
            node->u.b_val = 0;
        } else if (strcmp(buf, "null") == 0) {
            node->type = T_NULL;
        } else {
            node->type = T_NUMBER;
            node->u.n_val = atof(buf);
        }
        free(buf);
    }
    return node;
}

void print_json_final_v2(const json_node *node, int indent) {
    if (node->type == T_OBJECT) {
        printf("{\n");
        for (size_t i = 0; i < node->u.object.size; i++) {
            for (int j = 0; j < indent; j++) printf(" ");
            printf("\"%s\": ", node->u.object.keys[i]);
            print_json_final_v2(node->u.object.values[i], indent + 2);
            if (i < node->u.object.size - 1) printf(",");
            else printf("");
        }
        for (int j = 0; j < indent; j++) printf(" ");
        printf("}\n");
    } else if (node->type == T_ARRAY) {
        printf("[\n");
        for (size_t i = 0; i < node->u.array.size; i++) {
            for (int j = 0; j < indent; j++) printf(" ");
            print_json_final_v2(node->u.array.elements[i], indent + 2);
            if (i < node->u.array.size - 1) printf(",");
            else printf("");
        }
        for (int j = 0; j < indent; j++) printf(" ");
        printf("]\n");
    } else if (node->type == T_STRING) {
        printf("\"%s\"", node->u.s_val);
    } else if (node->type == T_NUMBER) {
        printf("%g", node->u.n_val);
    } else if (node->type == T_BOOL) {
        printf("%s", node->u.b_val ? "true" : "false");
    } else if (node->type == T_NULL) {
        printf("null");
    }
}

char *read_file(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc(len + 1);
    if (buf) {
        fread(buf, 1, len, f);
        buf[len] = '\0';
    }
    fclose(f);
    return buf;
}

int main() {
    const char *path_a = "/tmp/…/config_a.json";
    const char *path_b = "/tmp/…/config_b.json";
    char *buf_a = read_file(path_a);
    char *buf_b = read_file(path_b);
    if (!buf_a || !buf_b) return 0;
    const char *cursor_a = buf_a;
    const char *cursor_b = buf_b;
    json_node *a = parse_json(&cursor_a);
    json_node *b = parse_json(&cursor_b);
    json_node *merged = merge(a, b);
    print_json_final_v2(merged, 0);
    free_node(a);
    free_node(b);
    free_node(merged);
    free(buf_a);
    free(buf_b);
    return 0;
}
